  ('e4f3bfab-6a14-5fdf-9c41-6256d688b8a4', '65b6b32a-ccd6-5f03-89fa-61f6e774894e', 1, 'published', '{"en":{"inline":{"holisticAdministrativeTeam":"Administrative Team","holisticClosingTitle":"Making care instinctive","holisticResearchTeam":"Research Team","skipToContent":"Skip to content"},"strings":{"aiBody":"Centered on building an AI holistic-care education ecosystem, this scope connects holistic care education, AI expertise, medical-education research and real practice settings — developing AI-assisted teaching resources, case materials and assessment feedback for clinical and campus use, deepening empathy, communication and whole-person care.","aiTitle":"Healthy Taiwan Deep Cultivation, Scope 2: Building an AI Holistic Care Education Ecosystem","backDept":"Back to Dept.","brand1":"Taipei Medical Univ. Hospital","brand2":"Dept. of Medical Education","chipCenters":"Education Centers","chipSeed":"Seed Teachers","comingSoon":"Coming soon","contactTitle":"Contact Us","ctaOrg":"Explore the Organization","dept":"Dept. of Medical Education","deptShort":"MED EDU","eventsDesc":"Courses, talks and training. Will connect live to the department activity platform, auto-showing events with online registration.","eventsEn":"Activities","eventsZh":"Activities","footAddr":"No. 252, Wuxing St., Xinyi Dist., Taipei 110301, Taiwan","footBrand":"Dept. of Medical Education, TMU Hospital","footBrandEn":"Taipei Medical University Hospital","footNote":"© Taipei Medical University Hospital, Dept. of Medical Education. For unit display only.","footTel":"Tel: (02) 2737-2181","formingTeam":"Team being formed — stay tuned.","hAboutBody":"Holistic Care holds that health is not merely the absence of disease, but the whole-person wellbeing of body, mind, society and spirit. We begin with education, so every clinician can offer care and first-line support.","hAboutTitle":"About the Center","hContactExt":"(02) 2737-2181 ext. 3760","hContactPerson":"Administrator: Ming-Hsien Chiang","hContactPlace":"TMU Hospital · Holistic Care Education Center, Dept. of Medical Education","hContactQuote":"Education that makes holistic care second nature to every clinician.","hCtaMhfa":"Learn about MHFA","heroEyebrow":"Taipei Medical University Hospital","heroTag":"People-centered whole-person medical education — uniting faculty development, clinical skills, evidence-based medicine and holistic care to nurture compassionate, competent clinicians.","heroTitle1":"Excellence in","heroTitle2":"Medical Education","hHeroTag":"The Center unites medical, psychological and compassionate care to promote Mental Health First Aid, nurturing interdisciplinary seed teachers so support reaches every clinical setting and campus corner.","hHeroTitle":"People first — caring for the whole person","hospital":"Taipei Medical University Hospital","instructorsTitle":"Center Instructors","kpiEyebrow":"At a Glance","kpiTitle":"The Department at a Glance","langBtn":"中","layoutHub":"Hub","layoutTree":"Tree","members":"Team Members","mhfaIntro":"Like CPR for the body, MHFA teaches us to notice, accompany and help refer someone in psychological distress or crisis. Tap each letter to explore the five action steps.","mhfaTitle":"Mental Health First Aid · ALGEE","navAbout":"About","navContact":"Contact","navHolistic":"Holistic Care","navMhfa":"MHFA","navNews":"News","navOrg":"Organization","navSeed":"Seed Teachers","newsDesc":"Latest news from the center and the department. Once connected to the activity platform, the public board will appear here automatically.","newsEn":"Announcements","newsZh":"Announcements","orgDesc":"Six functional units working in concert. Tap any center to view its services and contact.","orgTitle":"Organizational Structure","seedDesc":"From 11 departments across 10 professional disciplines, carrying the seeds of mental health first aid back to their own workplaces.","seedTitle":"MHFA Seed Teacher Team"}},"zh":{"inline":{"holisticAdministrativeTeam":"行政團隊","holisticClosingTitle":"讓關懷成為本能","holisticResearchTeam":"研究團隊","skipToContent":"跳到主要內容"},"strings":{"aiBody":"本範疇以「打造 AI 全人照護教育生態系」為核心，串連全人照護教育、人工智慧專業、醫學教育研究與實作場域，發展可導入臨床與校園的 AI 輔助教學資源、案例素材與評量回饋機制，支持醫療人才在科技輔助下深化同理、溝通與全人照護能力。","aiTitle":"台灣健康深耕計畫範疇二： 打造 AI 全人照護教育生態系","backDept":"返回教學部","brand1":"臺北醫學大學附設醫院","brand2":"教學部 · Medical Education","chipCenters":"教育中心","chipSeed":"種子教師","comingSoon":"即將串接","contactTitle":"聯絡我們","ctaOrg":"探索組織架構","dept":"教學部","deptShort":"教學部","eventsDesc":"課程、講座與培訓資訊。未來將與「教學部活動管理平台」即時串接，自動顯示最新活動並開放線上報名。","eventsEn":"Activities","eventsZh":"近期活動","footAddr":"地址：110301 臺北市信義區吳興街 252 號","footBrand":"臺北醫學大學附設醫院 教學部","footBrandEn":"Dept. of Medical Education · TMU Hospital","footNote":"© 臺北醫學大學附設醫院 教學部　本網站僅供單位展示使用。","footTel":"電話：(02) 2737-2181","formingTeam":"團隊籌備中，敬請期待。","hAboutBody":"全人照護（Holistic Care）相信健康不只是沒有疾病，而是身、心、社會與心靈的整⁠體⁠安⁠適。我們以教育為起點，讓每一位醫療同仁都具備關懷與初步協助的能力。","hAboutTitle":"關於全人照護教育中心","hContactExt":"(02) 2737-2181 ＃3760","hContactPerson":"行政專員：江明憲","hContactPlace":"臺北醫學大學附設醫院 · 教學部 全人照護教育中心","hContactQuote":"以教育推動全人照護，讓關懷成為每一位醫療人的本能。","hCtaMhfa":"了解心理健康急救","heroEyebrow":"Taipei Medical University Hospital","heroTag":"以人為本的全人醫療教育，結合教師發展、臨床技能、實證醫學與全人照護，培育兼具同理心與專業能力的醫療人才。","heroTitle1":"卓越醫學教育","heroTitle2":"育成醫療人才","hHeroTag":"全人照護教育中心結合醫療、心理與關懷的力量，推動「心理健康急救 Mental Health First Aid」，培育跨領域種子教師，讓身心健康的支持，走進每一個臨床現場與校園角落。","hHeroTitle":"以人為本，照顧每一個完整的人","hospital":"臺北醫學大學附設醫院","instructorsTitle":"中心指導員","kpiEyebrow":"At a Glance","kpiTitle":"教學部一覽","langBtn":"EN","layoutHub":"中樞圖","layoutTree":"組織樹","members":"團隊成員","mhfaIntro":"就像 CPR 之於身體急救，MHFA 教我們在他人陷入心理困擾或危機時，能夠及時察覺、陪伴與協助轉介。點選每個字母，認識五個行動步驟。","mhfaTitle":"心理健康急救 ALGEE","navAbout":"關於","navContact":"聯絡","navHolistic":"全人照護中心","navMhfa":"心理健康急救","navNews":"公告","navOrg":"組織架構","navSeed":"種子教師","newsDesc":"中心與教學部的最新訊息。未來與活動管理平台串接後，將自動顯示「對外看板」的公告。","newsEn":"Announcements","newsZh":"最新公告","orgDesc":"六大功能單位協同運作，點擊任一中心查看核心業務與聯絡窗口。","orgTitle":"教學部組織架構","seedDesc":"來自全院 11 個科部、橫跨 10 種專業職類，將心理健康急救的種子帶回各自的工作現場。","seedTitle":"MHFA 種子教師團隊"}}}'::jsonb, '2026-08-14T00:00:00.000Z'::timestamptz),
  ('d93b7817-cac1-5a1f-9839-cb10192ffd70', 'f48185ca-0292-546f-8e39-d08dec129203', 1, 'published', '{"en":{"centers":[{"branches":[{"description":"The core platform for hospital-wide faculty development and academic appointments.","icon":"cap","id":"about","name":"About","pageSection":"fd-about","panelSection":"intro"},{"description":"Systematic faculty cultivation, teaching quality, and cross-profession support.","icon":"book","id":"services","name":"Services","pageSection":"fd-services","panelSection":"detail"},{"description":"Administrator Chun-Ju Chen, ext. 3757.","icon":"phone","id":"contact","name":"Contact","pageSection":"fd-contact","panelSection":"contact"}],"color":"#A87A6B","contact":"Chun-Ju Chen","ext":"3757","id":"faculty_dev","intro":"Hospital-wide clinical faculty development and support for academic appointments, strengthening teaching quality and professional growth.","name":"Center for Faculty Development"},{"branches":[{"description":"OSCE and simulation training for solid clinical skills.","icon":"skills","id":"about","name":"About","panelSection":"intro"},{"description":"Planning, delivery, and assessment of OSCE and simulation-based training.","icon":"clipboard","id":"services","name":"Services","panelSection":"detail"},{"description":"Chia-Ming Chang & Che-Min Lai, ext. 3772.","icon":"phone","id":"contact","name":"Contact","panelSection":"contact"}],"color":"#5E7A8C","contact":"Chia-Ming Chang · Che-Min Lai","ext":"3772","externalUrl":"https://tmuh-education.tmuh.org.tw/center/about/clinical/abt02","id":"clinical_skills","intro":"Designing and running OSCE and simulation-based training to build solid clinical skills.","name":"Center for Clinical Skills"},{"branches":[{"description":"Advancing EBM and embedding best evidence in clinical decisions.","icon":"chart","id":"about","name":"About","pageSection":"ebm-about","panelSection":"intro"},{"description":"Training, EBM courses, and quality improvement fostering an evidence-based culture.","icon":"bulb","id":"services","name":"Services","pageSection":"ebm-missions","panelSection":"detail"},{"description":"Administrator Ming-Hsien Chiang, ext. 3760.","icon":"phone","id":"contact","name":"Contact","pageSection":"ebm-contact","panelSection":"contact"}],"color":"#B69B66","contact":"Ming-Hsien Chiang","ext":"3760","id":"ebm","intro":"Advancing Evidence-Based Medicine, embedding evidence into care quality and clinical decisions.","name":"Center for Evidence-Based Medicine"},{"branches":[{"description":"People-first holistic care and medical humanities education.","icon":"holistic","id":"about","name":"About","pageSection":"h-about","panelSection":"intro"},{"description":"Mental Health First Aid outreach, interdisciplinary seed-teacher training, and holistic-care programs.","icon":"heart","id":"services","name":"Services","pageSection":"mhfa","panelSection":"detail"},{"description":"Administrator Ming-Hsien Chiang, ext. 3760.","icon":"phone","id":"contact","name":"Contact","pageSection":"h-contact","panelSection":"contact"}],"color":"#4f8c7d","contact":"Ming-Hsien Chiang","deep":true,"ext":"3760","id":"holistic","intro":"People first — caring for the whole person. Uniting medical, psychological and compassionate care to promote Mental Health First Aid.","name":"Center for Education in Holistic Care and Human Flourishing"},{"branches":[{"description":"Evidence- and data-driven medical education research.","icon":"research","id":"about","name":"About","panelSection":"intro"},{"description":"Outcomes analysis, assessment-tool development, and curriculum feedback.","icon":"chart","id":"services","name":"Services","panelSection":"detail"},{"description":"Administrator Li-Yu Chen, ext. 3760.","icon":"phone","id":"contact","name":"Contact","panelSection":"contact"}],"color":"#6E8A77","contact":"Li-Yu Chen","ext":"3760","externalUrl":"https://tmuh.ai/u/jc2jc/med-ed-research-center/?lang=en#overview","id":"med_edu_research","intro":"Studying medical education with evidence- and data-driven methods, developing assessment tools and feeding findings back into curriculum design.","name":"Center for Research in Medical Education"},{"branches":[{"description":"VP, directors, deputies, and section head.","icon":"admin","id":"leadership","name":"Leadership","panelSection":"intro"},{"description":"Specialists supporting all centers by duty area.","icon":"team","id":"duties","name":"Duties","panelSection":"team"},{"description":"Verified desk extensions for key contacts.","icon":"phone","id":"extensions","name":"Extensions","panelSection":"contact"}],"color":"#8a8076","contact":"","ext":"","id":"admin","intro":"Working in coordinated roles — from the VP for Medical Education and department directors to administrative specialists — to support all teaching operations.","name":"Administrative Team"}]},"zh":{"centers":[{"branches":[{"description":"全院臨床教師培育與教職支援的核心平台。","icon":"cap","id":"about","name":"簡介","pageSection":"fd-about","panelSection":"intro"},{"description":"系統性師資培育、教學品質提升與跨職類教師支持。","icon":"book","id":"services","name":"核心業務","pageSection":"fd-services","panelSection":"detail"},{"description":"行政專員陳均茹，分機 3757。","icon":"phone","id":"contact","name":"聯絡","pageSection":"fd-contact","panelSection":"contact"}],"color":"#A87A6B","contact":"陳均茹","ext":"3757","id":"faculty_dev","intro":"全院臨床教師培育，並協助學校教職相關事務，提升整體教學品質與師資專業發展。","name":"教師發展中心"},{"branches":[{"description":"規劃 OSCE 與模擬訓練，培養紮實臨床技能。","icon":"skills","id":"about","name":"簡介","panelSection":"intro"},{"description":"客觀結構式臨床測驗（OSCE）與模擬訓練的規劃、執行與評量。","icon":"clipboard","id":"services","name":"核心業務","panelSection":"detail"},{"description":"張家銘、賴哲民，分機 3772。","icon":"phone","id":"contact","name":"聯絡","panelSection":"contact"}],"color":"#5E7A8C","contact":"張家銘、賴哲民","ext":"3772","externalUrl":"https://tmuh-education.tmuh.org.tw/center/about/clinical/abt02","id":"clinical_skills","intro":"規劃並執行醫學生客觀結構式臨床測驗（OSCE）與各式模擬訓練，培養紮實的臨床技能。","name":"臨床技能中心"},{"branches":[{"description":"推動實證醫學，將最佳證據融入臨床決策。","icon":"chart","id":"about","name":"簡介","pageSection":"ebm-about","panelSection":"intro"},{"description":"教育培訓、實證課程與品質改善，推動全院實證文化。","icon":"bulb","id":"services","name":"核心業務","pageSection":"ebm-missions","panelSection":"detail"},{"description":"行政專員江明憲，分機 3760。","icon":"phone","id":"contact","name":"聯絡","pageSection":"ebm-contact","panelSection":"contact"}],"color":"#B69B66","contact":"江明憲","ext":"3760","id":"ebm","intro":"推動實證醫學（EBM），將實證精神落實於醫療品質，提升臨床決策與照護成效。","name":"實證醫學中心"},{"branches":[{"description":"以人為本，推動全人照護與醫學人文教育。","icon":"holistic","id":"about","name":"簡介","pageSection":"h-about","panelSection":"intro"},{"description":"心理健康急救（MHFA）推廣、跨領域種子教師培育與全人照護推動計畫。","icon":"heart","id":"services","name":"核心業務","pageSection":"mhfa","panelSection":"detail"},{"description":"行政專員江明憲，分機 3760。","icon":"phone","id":"contact","name":"聯絡","pageSection":"h-contact","panelSection":"contact"}],"color":"#4f8c7d","contact":"江明憲","deep":true,"ext":"3760","id":"holistic","intro":"以人為本，照顧每一個完整的人。結合醫療、心理與關懷的力量，推動「心理健康急救 MHFA」，培育跨領域種子教師。","name":"全人照護教育中心"},{"branches":[{"description":"以實證與資料驅動方法研究醫學教育。","icon":"research","id":"about","name":"簡介","panelSection":"intro"},{"description":"教學成效分析、評量工具開發與課程回饋，支持教師與課程精進。","icon":"chart","id":"services","name":"核心業務","panelSection":"detail"},{"description":"行政專員陳麗玉，分機 3760。","icon":"phone","id":"contact","name":"聯絡","panelSection":"contact"}],"color":"#6E8A77","contact":"陳麗玉","ext":"3760","externalUrl":"https://tmuh.ai/u/jc2jc/med-ed-research-center/?lang=zh#overview","id":"med_edu_research","intro":"以實證與資料驅動的方法研究醫學教育，發展教學評量工具與成效分析，將研究成果回饋至課程設計與教師發展。","name":"醫學教育研究中心"},{"branches":[{"description":"教學副院長、部主任、副主任與組長。","icon":"admin","id":"leadership","name":"領導團隊","panelSection":"intro"},{"description":"行政專員依業務領域分工支援五大中心。","icon":"team","id":"duties","name":"業務分工","panelSection":"team"},{"description":"各窗口已確認的桌機分機一覽。","icon":"phone","id":"extensions","name":"分機資訊","panelSection":"contact"}],"color":"#8a8076","contact":"","ext":"","id":"admin","intro":"依職責與分工協同運作，從教學副院長、教學部主任、副主任、組長到各行政專員，支援教學部各項業務的推動。","name":"行政團隊"}]}}'::jsonb, '2026-08-14T00:00:00.000Z'::timestamptz),
