  ('8d4ade0d-487f-5c13-9e8e-086acb46bfe9', '244726af-6530-5a1c-84a1-3f2fd14fc718', 1, 'published', '{"en":{"categories":{"department":[{"id":"achievement","label":"Achievements"},{"id":"department","label":"Department"}],"holistic":[{"id":"international","label":"International"}]},"department":[{"category":"achievement","categoryLabel":"Achievements","date":"May 20, 2026","delay":0,"lines":["A THSS surgical paper accepted by the top journal International Journal of Surgery (Q1, IF 10.3).","International conferences: AMEE ×3, ISQua ×3;","ISQua 2026 granted a 30-min session using a Virtual Patient to explore pain control in the rare disease Calciphylaxis, praised by the organizers."],"pinned":true,"statBot":"IF 10.3","statBotLabel":"Impact factor","statFont":"40px","statTop":"Q1","statTopLabel":"Journal Q","tag":"Pinned","tagBg":"color-mix(in srgb,#B07A4A 14%,transparent)","tagColor":"#B07A4A","title":"Scholarship & the international stage"},{"category":"department","categoryLabel":"Department","date":"May 1, 2023","delay":70,"lines":["Established within the Dept. of Medical Education under the Center''s founding charter;","Competency-oriented, advancing teaching practice and applied research in holistic care, spiritual care and medical humanities, supporting every unit in raising holistic-care quality."],"pinned":false,"statFont":"26px","statTop":"112.05.01","statTopLabel":"Founded","tag":"News","tagBg":"color-mix(in srgb,#4f8c7d 13%,transparent)","tagColor":"#4f8c7d","title":"The Center is officially established"}],"holistic":[{"category":"international","categoryLabel":"International","date":"Apr 15, 2026","delay":0,"lines":["Deputy Director Tereza Vafkova of the virtual medical faculty at Masaryk University (Czechia) gave a campus keynote.","56 physicians, professors and researchers joined online and in person, deepening holistic-care and AI-assisted teaching exchange under the Healthy Taiwan initiative."],"pinned":false,"statFont":"40px","statTop":"56","statTopLa