  ('b4765ef8-ab7c-5300-94e2-9e7079f81388', '73f822bb-290e-50de-89ae-2c62363c87b9', 1, 'published', '{"en":{"aboutBody":"Within the Department of Medical Education, Director Ming-De Chen leads a team responsible for hospital-wide faculty cultivation and academic-appointment affairs — systematic curricula, accreditation alignment and a committee mechanism that continually raises teaching quality.","aboutBody2":"Six cultivation groups span CBME, sustainability, technology-enhanced teaching, evidence-based medicine and holistic care — rooting pedagogical expertise across every domain.","aboutEyebrow":"Mission & Positioning","aboutTitle":"Faculty growth, the root of medical education","actEyebrow":"Activities","actTitle":"Activities","closingBody":"Through systematic cultivation, appointment support and six collaborating groups, the Center helps clinical teachers across all professions grow — laying deep roots for the sustainable future of medical education.","closingTitle":"Great teachers are the deepest roots of medical education","colors":{"blue":"#7A95A8","clay":"#A87A6B","claySoft":"#C49A8C","ink":"#3A2E25","ochre":"#B69B66","sage":"#8FA898"},"contactExt":"(02) 2737-2181 ext. 3757","contactPerson":"Administrator: Chun-Ju Chen","contactPlace":"TMU Hospital · Center for Faculty Development, Dept. of Medical Education","contactQuote":"To grow a teacher is to grow every future caregiver.","eyebrow":"Center for Faculty Development","groupLeadLabel":"Lead","groupRoot":"Center for Faculty Development","groups":[{"desc":"Competency-based curriculum design and milestone frameworks.","lead":{"alternateName":"邱欣怡","department":"Physician · Asst. Prof.","duty":"","email":"","ext":"","hubId":"hsin-yi-chiu","name":"Hsin-Yi Chiu","portrait":{"kind":"local","path":"assets/hsin-yi-chiu.jpg"},"role":"Lead","roleKey":"lead","slug":"hsin-yi-chiu"},"name":"CBME · Curriculum","tone":"#A87A6B"},{"desc":"Mini-CEX, DOPS, CbD tools and EPA reliability/validity analysis.","lead":{"alternateNa